    ('AddBounty', 'Add_Bounty', '#HERIKA_NAME# adds a crime bounty to #PLAYER_NAME# for a witnessed or reported crime. Guard-only action.', '#HERIKA_NAME# added a bounty for #TARGET# to #PLAYER_NAME#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"item":{"type":"string","description":"Custom gold amount (only used when crime_type is Custom)"},"target":{"enum":["Assault","Murder","Theft","Pickpocketing","Trespassing","Jailbreak","Custom"],"type":"string","description":"Crime type for the bounty"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"You just added a bounty to #PLAYER_NAME#. React in character. You may follow up with another action if appropriate.","enabled":true,"arg_name":"target","use_functions_again":true},"requirements":{"npc_factions_any":["00086EEE","00028848","00028849"]}}'::jsonb, TRUE, 0, NULL),
    ('ArrestPlayer', 'Arrest_#PLAYER_NAME#', '#HERIKA_NAME# attempts to arrest #PLAYER_NAME#. #PLAYER_NAME# can submit or resist. Guard-only action for serious crimes or refusal to pay.', '#HERIKA_NAME# attempted to arrest #PLAYER_NAME#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[""],"properties":{"target":{"type":"string","description":"Keep it blank"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"You attempted to arrest #PLAYER_NAME#. They get a submit or resist prompt; resist starts combat. Reply with one short stern final line. Do not ask follow-up questions.","enabled":true,"arg_name":"target"},"requirements":{"npc_factions_any":["00086EEE","00028848","00028849"]}}'::jsonb, TRUE, 0, NULL),
    ('Attack', 'Attack', 'Attack with intention to kill a target actor or entity.', '#HERIKA_NAME# attacks #TARGET#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"Target NPC, Actor, or being"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"Reply with one short in-character combat line reacting to the attack outcome. Do not ask follow-up questions.","enabled":false,"arg_name":"target"}}'::jsonb, TRUE, 0, NULL),
    ('Brawl', 'Brawl', '#HERIKA_NAME# starts a brawl with #PLAYER_NAME# or another nearby NPC: an agreed, bare-fisted fight that is not meant to kill. Fists only, no weapons, shields, spells, staves, or poisons. Use Attack instead when #HERIKA_NAME# truly means to kill.', '#HERIKA_NAME# starts a brawl with #TARGET#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"Who #HERIKA_NAME# brawls: a nearby NPC, actor, or #PLAYER_NAME#. Prefer exact Name [RefID: XXXXXXXX] from people_present; otherwise use the actor name."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('CastSpell', 'Cast_Spell', '#HERIKA_NAME# casts a spell on a target actor. Must specify spell name from <spells> and target actor name. Use ''self'' as target for self-targeted spells.', '#HERIKA_NAME# casts #ITEM# on #TARGET#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target","item"],"properties":{"item":{"type":"string","description":"REQUIRED: Spell name from <spells> tag (exact name)"},"target":{"type":"string","description":"Target actor name, or ''self'' for self-cast spells"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('CheckInventory', 'Check_Inventory', 'Search in #HERIKA_NAME#''s inventory, backpack, or pocket. List their inventory contents.', '#HERIKA_NAME#''s INVENTORY:#RESULT#', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"item to look for, if empty all items will be returned"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"Reply with one short in-character line about the inventory result below. Do not ask follow-up questions.","enabled":true,"arg_name":"target"}}'::jsonb, TRUE, 0, NULL),
