    ('Consume', 'Consume', '#HERIKA_NAME# consumes a food, drink, or potion from inventory. Use the exact inventory item name in the target field.', '#HERIKA_NAME# consumes an item from inventory.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"item":{"type":"string","description":"Optional fallback copy of the same inventory item name if target is empty."},"target":{"type":"string","description":"REQUIRED: Exact name of the food, drink, or potion from <inventory> to consume."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"enabled":false}}'::jsonb, TRUE, 0, NULL),
    ('CreateNewNPC', 'Create_New_NPC', 'Create and spawn a brand-new nearby NPC from a short creation brief.', 'A new NPC is being created nearby.', FALSE, FALSE, TRUE, FALSE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"REQUIRED: short creation brief for the new nearby NPC."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"server_action"}'::jsonb, FALSE, 0, NULL),
    ('DirectorCommand', 'Director_Command', 'Send a short freeform director instruction to the server-side director mode so it can stage a scene or event.', 'The director is preparing a scene instruction.', FALSE, FALSE, TRUE, FALSE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"REQUIRED: short freeform director brief describing the scene instruction or event to stage."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"server_action"}'::jsonb, FALSE, 0, NULL),
    ('DecreaseWalkSpeed', 'Decrease_Walk_Speed', 'Decrease #HERIKA_NAME#''s speed when moving or travelling.', 'Decreases #HERIKA_NAME#''s speed or pace when moving or travelling.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"speed":{"enum":["jog","walk"],"type":"string","description":"Speed"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('Drink', 'Drink', 'Drinks a beverage to quench thirst or enjoy flavor.', '#HERIKA_NAME# drinks a beverage to quench thirst or enjoy flavor.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[""],"properties":{"target":{"type":"string","description":"Keep it blank"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"script_proxy","requirements":{"activity":{"current_action_not_in":["sitting"]}}}'::jsonb, TRUE, 0, '{"cases":{"Chair":{"commands":[{"args":{"akIdle":"0x00065d07","targetObjectFormId":"{{actor_refid}}"},"cmd_id":34}]},"__default":{"commands":[{"args":{"akIdle":"0x00103656","targetObjectFormId":"{{actor_refid}}"},"cmd_id":34}]}},"switch_on":"actor_furniture","db_inserts":[{"data":{"ts":"{{request_ts}}","action":"Drink","gamets":"{{game_ts}}","localts":"{{local_ts}}","fullcall":"{{full_call}}","original":"","actorname":"{{actor_name}}"},"table":"actions_issued"}]}'::jsonb),
