    ('EndRitualCeremony', 'End_Ritual_Ceremony', 'Concludes a ritual or ceremony, marking its completion.', '#HERIKA_NAME# concludes a ritual or ceremony, marking its completion.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[""],"properties":{"target":{"type":"string","description":"Keep it blank"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"script_proxy","requirements":{"activity":{"current_action_in":["ritual"]}}}'::jsonb, TRUE, 0, '{"commands":[{"args":{"akIdle":"0x000f11e3","targetObjectFormId":"{{actor_refid}}"},"cmd_id":34}],"db_inserts":[{"data":{"ttl":30,"data":"{{actor_name}} just ended the ritual celebration","type":"scenenote","localts":"{{local_ts}}"},"table":"rolemaster"},{"data":{"ts":"{{request_ts}}","action":"EndRitualCeremony","gamets":"{{game_ts}}","localts":"{{local_ts}}","fullcall":"{{full_call}}","original":"","actorname":"{{actor_name}}"},"table":"actions_issued"}],"npc_metadata_updates":{"ritual_state":null,"activity_status":{"gamets":"{{game_ts}}","use_type":"","timestamp":"{{local_ts_ms}}","current_use":"","current_action":"idle","furniture_name":""}}}'::jsonb),
