    ('FollowPlayer', 'Follow_#PLAYER_NAME#', '#HERIKA_NAME# follows #PLAYER_NAME#.', '#HERIKA_NAME# follows #PLAYER_NAME#.', TRUE, FALSE, FALSE, TRUE, '{"type":"object","required":[""],"properties":{"target":{"type":"string","description":""}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"enabled":false},"cooldown_seconds":60}'::jsonb, TRUE, 0, NULL),
    ('ForgiveCrime', 'Forgive_Crime', '#HERIKA_NAME# forgives #PLAYER_NAME#''s crimes and clears their bounty. Guard-only action for persuasion, bribe, or thane status.', '#HERIKA_NAME# forgave #PLAYER_NAME#''s crimes and cleared their bounty.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[""],"properties":{"target":{"type":"string","description":"Keep it blank"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"You forgave #PLAYER_NAME#''s crimes and cleared their bounty. Reply with one short in-character acknowledgment, warning, or blessing. Do not ask follow-up questions.","enabled":false,"arg_name":"target"},"requirements":{"npc_factions_any":["00086EEE","00028848","00028849"]}}'::jsonb, TRUE, 0, NULL),
    ('GiveGoldTo', 'Give_Gold_To', '#HERIKA_NAME# gives gold, coins, or septims to another actor or #PLAYER_NAME#. REQUIRED: Must include ''target'' field with recipient name and ''item'' field with amount as a number string.', '#HERIKA_NAME# gives #ITEM# gold to #TARGET#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target","item"],"properties":{"item":{"type":"string","description":"Amount of gold to give (number as string)"},"target":{"type":"string","description":"Target NPC, Actor, or being to receive gold"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"Reply with one short in-character line reacting to the gold transfer result below. Do not ask follow-up questions.","enabled":false,"arg_name":"target"}}'::jsonb, TRUE, 0, NULL),
    ('GiveItemTo', 'Give_Item_To', '#HERIKA_NAME# gives a specific item from inventory to another actor or #PLAYER_NAME#. REQUIRED: Must include ''item'' field with exact item name from <inventory> tag, and ''target'' field with recipient name.', '#HERIKA_NAME# gives #ITEM# to #TARGET#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target","item"],"properties":{"item":{"type":"string","description":"REQUIRED: Exact name of item from <inventory> tag. Must match item name exactly."},"amount":{"type":"integer","description":"Number of items to give (default: 1). Cannot exceed quantity in <inventory>."},"target":{"type":"string","description":"Target NPC, Actor, or being to receive the item"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"Reply with one short in-character line reacting to the item handoff result below. Do not ask follow-up questions.","enabled":false,"arg_name":"target"}}'::jsonb, TRUE, 0, NULL),
    ('GoToSleep', 'Go_To_Sleep', '#HERIKA_NAME# takes a nap.', '#HERIKA_NAME# takes a nap.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[""],"properties":{"target":{"type":"string","description":"Keep it blank"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","requirements":{"activity":{"current_action_not_in":["dead","unconscious","sleeping","combat","attacking"]}}}'::jsonb, TRUE, 0, NULL),
    ('HireCarriage', 'Hire_Carriage', '#HERIKA_NAME# accepts {{config.cost_gold}} gold for carriage travel and transports #PLAYER_NAME# to the specified destination. Reply with one short acceptance line, do not ask follow-up questions, then end the conversation.', '#HERIKA_NAME# accepted the {{config.cost_gold}} gold carriage fare to #TARGET# and ended the conversation.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"enum":["Whiterun","Solitude","Markarth","Riften","Windhelm","Morthal","Dawnstar","Falkreath","Winterhold","Darkwater Crossing","Dragon Bridge","Ivarstead","Karthwasten","Kynesgrove","Old Hroldan","Riverwood","Rorikstead","Shor''s Stone","Stonehills"],"type":"string","description":"Vanilla carriage destination for RANGROO"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"Reply with one short in-character line accepting payment and ending the conversation. Do not ask follow-up questions.","enabled":false,"arg_name":"target"},"requirements":{"activity":{"current_action_not_in":["dead","unconscious","sleeping","combat","attacking"]},"npc_name_in_action_config_list":{"config_key":"allowed_npc_names"}},"editor_fields":[{"key":"cost_gold","help":"How much gold this action costs.","type":"integer","label":"Gold Cost","format":"gold","default":20,"minimum":1},{"key":"allowed_npc_names","help":"Only these NPC names will offer carriage travel.","type":"textarea","label":"Allowed NPCs","format":"name_list","default":"Bjorlam\nAlfarinn\nKibell\nSigaar\nThaer\nEngar\nGunjar\nMarkus","placeholder":"One NPC name per line"}],"parameter_template":{"amount":"{{config.cost_gold}}","target":"{{parameter_target}}"}}'::jsonb, TRUE, 0, NULL),
    ('HireFerry', 'Hire_Ferry', '#HERIKA_NAME# accepts {{config.cost_gold}} gold for ferry travel and transports #PLAYER_NAME# to the specified destination. Reply with one short acceptance line, do not ask follow-up questions, then end the conversation.', '#HERIKA_NAME# accepted the {{config.cost_gold}} gold ferry fare to #TARGET# and ended the conversation.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"enum":["Windhelm","Dawnstar","Solitude","Icewater Jetty","Castle Volkihar","Giant''s Tooth"],"type":"string","description":"Vanilla ferry destination for RANGROO"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"Reply with one short in-character line accepting payment and ending the conversation. Do not ask follow-up questions.","enabled":false,"arg_name":"target"},"requirements":{"activity":{"current_action_not_in":["dead","unconscious","sleeping","combat","attacking"]},"npc_name_in_action_config_list":{"config_key":"allowed_npc_names"}},"editor_fields":[{"key":"cost_gold","help":"How much gold this action costs.","type":"integer","label":"Gold Cost","format":"gold","default":50,"minimum":1},{"key":"allowed_npc_names","help":"Only these NPC names will offer ferry travel.","type":"textarea","label":"Allowed NPCs","format":"name_list","default":"Gort\nHarlaug\nJolf","placeholder":"One NPC name per line"}],"parameter_template":{"amount":"{{config.cost_gold}}","target":"{{parameter_target}}"}}'::jsonb, TRUE, 0, NULL),
    ('IncreaseWalkSpeed', 'Increase_Walk_Speed', 'Increase #HERIKA_NAME#''s speed when moving or travelling.', 'Increases #HERIKA_NAME#''s speed or pace when moving or travelling.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"speed":{"enum":["run","jog"],"type":"string","description":"Speed"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('Inspect', 'Inspect', 'Inspect a nearby actor or being to get a closer read on their visible equipment, condition, and state.', '', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["target"],"properties":{"target":{"enum":[],"type":"string","description":"Nearby NPC, actor, or being to inspect more closely"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"Reply with one short in-character observation using the inspect result below. Do not ask follow-up questions.","enabled":true,"arg_name":"target"}}'::jsonb, TRUE, 0, NULL),
