    ('KillTarget', 'Kill_Target', 'Kill a chosen NPC, actor, or #PLAYER_NAME# immediately.', '#TARGET# is killed.', FALSE, FALSE, TRUE, FALSE, '{"type":"object","required":["target"],"properties":{"target":{"type":"string","description":"REQUIRED: actor to kill. Use #PLAYER_NAME#, PLAYER, or me to kill the player."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"rolecommand"}'::jsonb, TRUE, 0, NULL),
