    ('PayBounty', 'Pay_Bounty', '#PLAYER_NAME# pays off their bounty to #HERIKA_NAME#. Stolen items are confiscated and the matter is resolved immediately. Guard-only action.', '#PLAYER_NAME# paid off their bounty to #HERIKA_NAME#, and stolen items were removed from inventory.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[""],"properties":{"target":{"type":"string","description":"Keep it blank"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"#PLAYER_NAME# has already paid the bounty and stolen items were removed from inventory. This action is fully complete. Reply with one short confirmation line, do not ask follow-up questions, and end the conversation.","enabled":true,"arg_name":"target"},"requirements":{"npc_factions_any":["00086EEE","00028848","00028849"]}}'::jsonb, TRUE, 0, NULL),
    ('PickupItem', 'Pickup_Item', '#HERIKA_NAME# picks up a specific item from the ground. Use the exact RefID:ItemName format from nearby_items (e.g. 0x12345:Iron Sword).', '#HERIKA_NAME# picks up #ITEM#.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":["item"],"properties":{"item":{"type":"string","description":"REQUIRED: Exact RefID:ItemName from <nearby_items> tag (e.g., 0x12345:Iron Sword). Must match format exactly."},"target":{"type":"string","description":"Target actor (leave empty for PickupItem)"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command"}'::jsonb, TRUE, 0, NULL),
    ('ReadQuestJournal', 'Read_Quest_Journal', 'Only use if #PLAYER_NAME# explicitly asks about a quest. Read the quest journal and get information about current quests.', '', TRUE, TRUE, TRUE, TRUE, '{"type":"object","required":[""],"properties":{"id_quest":{"type":"string","description":"Specific quest to read. Leave blank to read current quests."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"Reply with one short in-character line about the quest journal result below. Do not ask follow-up questions.","enabled":true,"arg_name":"id_quest"}}'::jsonb, TRUE, 0, NULL),
    ('Relax', 'Relax', 'Stop whatever you are doing and relax at the current location.Used to Unwind,Loosen Up,Enjoy Moment,Chill', '#HERIKA_NAME# is relaxed. Time to enjoy life.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep it blank"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","requirements":{"activity":{"current_action_not_in":["dead","unconscious","sleeping","combat","attacking"]}},"cooldown_seconds":180}'::jsonb, TRUE, 0, NULL),
    ('RentRoom', 'Rent_Room', '#HERIKA_NAME# rents a room to #PLAYER_NAME# for {{config.cost_gold}} gold. Only innkeepers can use this action and it only applies to #PLAYER_NAME#.', '#HERIKA_NAME# rented a room to #PLAYER_NAME# for {{config.cost_gold}} gold.', TRUE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep it blank"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","followup":{"prompt":"Reply with one short in-character confirmation that the room rental is complete. Do not ask follow-up questions.","enabled":false,"arg_name":"target"},"requirements":{"activity":{"current_action_not_in":["dead","unconscious","sleeping"]},"npc_factions_any":["0005091B"]},"editor_fields":[{"key":"cost_gold","help":"How much gold this action costs.","type":"integer","label":"Gold Cost","format":"gold","default":10,"minimum":1}],"parameter_template":{"amount":"{{config.cost_gold}}"}}'::jsonb, TRUE, 0, NULL),
