    ('SheatheWeapon', 'Sheathe_Weapon', 'Sheathes/put away current weapon', 'Sheathes/put away current weapon', FALSE, TRUE, FALSE, TRUE, '{"type":"object","required":[],"properties":{"target":{"type":"string","description":"Keep it blank"}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"plugin_command","requirements":{"activity":{"require_fresh":true,"is_weapon_drawn":true,"current_action_not_in":["dead","unconscious","sleeping"]}}}'::jsonb, TRUE, 0, NULL),
    ('SpawnItem', 'Spawn_Item', 'Create a named item from the descriptions database and give it to a target actor or #PLAYER_NAME#.', '#TARGET# receives #ITEM#.', FALSE, FALSE, TRUE, FALSE, '{"type":"object","required":["item"],"properties":{"item":{"type":"string","description":"REQUIRED: item name from the descriptions database."},"amount":{"type":"integer","description":"Quantity to spawn and give (default: 1)."},"target":{"type":"string","description":"Recipient actor. Use #PLAYER_NAME#, PLAYER, or me to give the item to the player."}}}'::jsonb, '{"source":"functions.php","status":"active","builtin":true,"dispatch":"rolecommand"}'::jsonb, TRUE, 0, NULL),
